#!/usr/bin/bash

# install_to_emmc.sh
# ROCKNIX eMMC Installation Script (Clone from TF to eMMC)
# This script copies U-boot and the ROCKNIX FAT32 partition to the eMMC,
# regenerates the UUIDs to avoid conflicts, and creates a fresh STORAGE partition.

set -e

# ==========================================
# Set up Display Variables
# ==========================================
export XDG_RUNTIME_DIR=/var/run/0-runtime-dir
export WAYLAND_DISPLAY=wayland-1
export DISPLAY=:0.0

# ==========================================
# Base64 Embedded Images
# ==========================================
echo "" | base64 -d > /tmp/installing.png
echo "" | base64 -d > /tmp/success.png
echo "" | base64 -d > /tmp/failed.png

show_image() {
    local img=$1
    set +e
    killall -9 mpv 2>/dev/null
    set -e
    if [ -f "/tmp/$img" ]; then
        mpv --loop-file=inf --fullscreen --no-terminal "/tmp/$img" >/dev/null 2>&1 &
    fi
}

cleanup_on_error() {
    echo "An error occurred during installation!"
    show_image "failed.png"
    # Keep the error image on screen for a while
    sleep 10
}

trap cleanup_on_error ERR

echo "=== ROCKNIX eMMC Installation Script ==="
show_image "installing.png"

SRC_DISK="/dev/mmcblk1" # TF Card
DST_DISK="/dev/mmcblk0" # eMMC

# 1. 检查磁盘是否存在
if [ ! -b "$SRC_DISK" ] || [ ! -b "$DST_DISK" ]; then
    echo "Error: Could not find source ($SRC_DISK) or destination ($DST_DISK) disks."
    exit 1
fi

echo "Source (TF Card): $SRC_DISK"
echo "Destination (eMMC): $DST_DISK"

# 2. 获取源盘 (TF卡) ROCKNIX 分区的结束扇区
P1_START_SECTOR=$(cat /sys/block/$(basename $SRC_DISK)/$(basename $SRC_DISK)p1/start)
P1_SIZE_SECTORS=$(cat /sys/block/$(basename $SRC_DISK)/$(basename $SRC_DISK)p1/size)
P1_END=$((P1_START_SECTOR + P1_SIZE_SECTORS))

echo "Partition 1 (ROCKNIX) ends at sector $P1_END on source disk."

# 计算需要复制的总量 (包含 MB 为单位的大小)
# 加上 1MB (2048个扇区) 作为安全余量
DD_COUNT=$(( (P1_END * 512 / 1048576) + 1 ))

echo "Step 1: Cloning Bootloader and ROCKNIX partition (${DD_COUNT} MB)..."
# 克隆 MBR 分区表, U-boot 和 整个 FAT32 启动分区
dd if=$SRC_DISK of=$DST_DISK bs=1M count=$DD_COUNT
sync

# 重新加载 eMMC 的分区表
set +e
partprobe $DST_DISK || echo "Partprobe failed, continuing anyway..."
set -e
sleep 2

echo "Step 2: Modifying UUIDs and Disk Signature to prevent conflicts..."
# (1) 随机化 MBR Disk Identifier (4字节，位于 0x01B8/440 偏移处) 
# 防止 TF 卡和 eMMC 的 MBR ID 完全一样导致 Linux 挂载冲突
dd if=/dev/urandom of=$DST_DISK bs=1 seek=440 count=4 conv=notrunc

# (2) 随机化 eMMC 上的 ROCKNIX 分区 (FAT32) 的 UUID / Volume ID
echo "Generating new UUID for ${DST_DISK}p1..."
set +e
fatlabel -r -i ${DST_DISK}p1
FATLABEL_RET=$?
set -e

if [ $FATLABEL_RET -eq 0 ]; then
    echo "FAT32 UUID generated successfully via fatlabel."
else
    # 兼容性 Fallback：如果 fatlabel -r 失败，生成随机 32位 Hex 序列号写入
    NEW_UUID=$(head -c 4 /dev/urandom | hexdump -e '1/4 "%08X"')
    echo "Using manual fallback UUID: $NEW_UUID"
    fatlabel -i ${DST_DISK}p1 $NEW_UUID
fi

echo "Step 3: Creating and formatting new STORAGE partition..."
# 删除在克隆过程中带过来的指向原 TF 卡容量大小的无用第 2 分区 (以及可能的 3、4 分区)
# 直接用 dd 覆盖 MBR 中的分区表记录，避免 parted 报错 "outside the disk"
dd if=/dev/zero of=$DST_DISK bs=1 seek=462 count=48 conv=notrunc
set +e
partprobe $DST_DISK || true
set -e
sleep 1

# 创建新的第 2 分区 (STORAGE)，占满 eMMC 剩余所有空间
# 起始扇区紧接在 P1 的末尾 (由于 P1_END = START + SIZE，这里直接作为下一个分区的起始)
NEW_START=${P1_END}
parted -s $DST_DISK mkpart primary ext4 ${NEW_START}s 100%
sync
sleep 2

# 格式化新的 STORAGE 分区。mkfs.ext4 默认会自动生成全新的、完全不同的 UUID
echo "Formatting ${DST_DISK}p2 as EXT4..."
mkfs.ext4 -F -L STORAGE ${DST_DISK}p2

trap - ERR

echo "============================================="
echo "Installation complete!"
echo "ROCKNIX and bootloader have been installed to eMMC."
echo "The FAT32 and EXT4 partitions on eMMC now have unique UUIDs."
echo "Please power off, remove the TF card, and turn on the device to boot from eMMC."
echo "============================================="

show_image "success.png"
# Keep success image on screen indefinitely until user powers off
sleep infinity
